"""Code-generation planning shared by the generator and its tests: import this.

A method body is decided in exactly one place. `plan_method` maps a contract
method plus its pattern_matches entry to a `(strategy, detail)` pair:

- `"crud:<kind>"` — mechanical in-memory implementation. Kinds: `create`,
  `read_one`, `read_all`, `update`, `delete`, `filter`. Reached two ways: the
  tie-breaker says so (`effective_directive` returns `pattern STANDARD_CRUD`,
  `READ_ALL`, `FILTER_BY_FIELD`, or a `rule`), or — when step F never saw the
  method (no entry at all) — the name alone is unambiguous.
- `"stub"` — anything else (aggregates, guards, exports, gaps, open ties).
  The generator emits `raise NotImplementedError` with the directive and the
  refusal reason in the docstring, never an invented body. A stub is a
  work order for the LLM pass, not a defect.

`MODEL_TYPES` maps the closed model-type vocabulary to Python spellings;
anything else passes through verbatim when it looks like a reference
(`Optional[`, `List[`, a declared entity) and becomes `Any` otherwise, so an
unknown spelling is visible in the signature rather than guessed at.
"""

from kernel import tie_rules
from kernel.consistency.naming import normalize

MODEL_TYPES = {
    "int": "int",
    "string": "str",
    "boolean": "bool",
    "decimal": "Decimal",
    "datetime": "datetime",
    "date": "date",
    "text": "str",
    "float": "float",
}

# Method-name prefixes with an unambiguous mechanical reading. `get`/`find`
# are deliberately absent: `get_monthly_spending` aggregates while
# `get_product_by_id` reads, and a prefix rule cannot tell them apart — those
# stay stubs unless their pattern entry says otherwise.
CREATE_PREFIXES = ("create", "add", "insert", "save", "register", "make", "new")
READ_ONE_MARKERS = ("readone", "byid", "byemail", "byname", "bysku", "byisbn", "bycode")
READ_ALL_MARKERS = ("readall", "all", "list")
UPDATE_PREFIXES = ("update", "edit")
DELETE_PREFIXES = ("delete", "remove", "drop", "destroy")
FILTER_PREFIXES = ("find", "filter", "search", "query")

MECHANICAL_PATTERNS = frozenset({"STANDARD_CRUD", "READ_ALL", "FILTER_BY_FIELD"})


def sanitize(identifier, fallback="unnamed"):
    """A valid Python identifier for any name string, or `fallback`."""
    cleaned = "".join(
        character if character.isalnum() or character == "_" else "_"
        for character in str(identifier or "")
    ).strip("_")
    if not cleaned:
        return fallback
    if cleaned[0].isdigit():
        cleaned = "_" + cleaned
    return cleaned or fallback


def map_type(spelling, entity_names=()):
    """A Python type spelling for a model or parameter type string."""
    if not isinstance(spelling, str) or not spelling.strip():
        return "Any"
    text = spelling.strip()
    lowered = text.lower()
    if lowered in MODEL_TYPES:
        return MODEL_TYPES[lowered]
    if lowered in ("none", "null", "void", "nonetype"):
        return "None"
    known = {normalize(name) for name in entity_names}
    bare = normalize(text.split("[", 1)[0].split("|", 1)[0])
    if text[:1].isupper() or "[" in text or "|" in text or "optional" in lowered:
        if bare and (not known or bare in known or "[" in text or "|" in text
                     or "optional" in lowered or text[:1].isupper()):
            return text
    return "Any"


def classify_crud(method_name):
    """The mechanical CRUD kind of a method name, or None when ambiguous."""
    name = normalize(method_name or "")
    if not name:
        return None
    if name.startswith(CREATE_PREFIXES):
        return "create"
    if name.startswith(UPDATE_PREFIXES):
        return "update"
    if name.startswith(DELETE_PREFIXES):
        return "delete"
    if any(marker in name for marker in READ_ONE_MARKERS):
        return "read_one"
    if name.startswith(FILTER_PREFIXES):
        return "filter"
    if any(marker in name for marker in READ_ALL_MARKERS):
        return "read_all"
    return None


def plan_method(method, entry, entity_names=()):
    """Return `(strategy, detail)` for one contract method.

    `method` is the service_contracts/persistence_ports method object, `entry`
    its pattern_matches entry or None when step F never saw it. Detail is the
    CRUD kind, the rule id, or the stub reason — everything the emitter needs,
    nothing it must re-derive.
    """
    method = method if isinstance(method, dict) else {}
    name = method.get("name") if isinstance(method.get("name"), str) else ""
    if entry is not None:
        kind, payload = tie_rules.effective_directive(entry)
        if kind == "pattern" and payload in MECHANICAL_PATTERNS:
            crud = classify_crud(name)
            if crud is not None:
                return (f"crud:{crud}", payload)
            return ("stub", f"pattern {payload} with an unreadable method name")
        if kind == "rule":
            crud = classify_crud(name)
            if crud is not None:
                return (f"crud:{crud}", payload)
            return ("stub", f"rule {payload} with an unreadable method name")
        if kind == "llm-gap":
            return ("stub", _gap_reason(payload))
        return ("stub", _tie_reason(payload))
    crud = classify_crud(name)
    if crud is not None:
        return (f"crud:{crud}", "name-only: step F never saw this method")
    return ("stub", "no pattern entry and an ambiguous method name")


def _gap_reason(payload):
    claimed = (payload or {}).get("claimed_pattern_id")
    rejection = (payload or {}).get("rejection")
    if claimed:
        return f"gap: {claimed} refused ({rejection})"
    return "gap: no pattern covers this method"


def _tie_reason(payload):
    candidates = (payload or {}).get("candidates") or []
    if candidates:
        return f"open tie between {' and '.join(candidates)}: review skipped"
    return "unclassifiable match entry"

"""In-memory record store for generated programs: no dependencies, no surprises.

Records are plain dicts keyed by field name. The store knows nothing about
your domain: every operation takes the entity name, the primary-key field,
and explicit criteria, so a wrong call fails loudly (`KeyError`, `ValueError`)
instead of filtering on a field that does not exist.

Criteria are `(field, operator, value)` triples with operators `eq`, `ge`,
`le`. `None` values never reach here — callers skip them — so every criterion
is a real constraint.
"""


class Store:
    """Maps entity names to `{primary_key_value: record}` dicts."""

    def __init__(self):
        self._records = {}
        self._next_id = {}

    def _space(self, entity):
        return self._records.setdefault(entity, {})

    def add(self, entity, pk_name, values, check_fk=(), error=None):
        """Store a copy of `values`; assign an integer key when it is None."""
        space = self._space(entity)
        record = dict(values)
        key = record.get(pk_name)
        if key is None:
            key = self._next_id.get(entity, 1)
            while key in space:
                key += 1
            record[pk_name] = key
            self._next_id[entity] = key + 1
        elif key in space:
            raise ValueError(f"{entity} with {pk_name}={key!r} already exists")
        for field_name, target_entity, target_field, exc in check_fk:
            self._check_fk(entity, record, field_name,
                           target_entity, target_field, exc)
        space[key] = record
        if error is not None and key is None:  # pragma: no cover - defensive
            raise error
        return dict(record)

    def _check_fk(self, entity, record, field_name,
                  target_entity, target_field, exc):
        value = record.get(field_name)
        if value is None:
            return
        for candidate in self._space(target_entity).values():
            if candidate.get(target_field) == value:
                return
        message = (f"{entity}.{field_name}={value!r} references missing "
                   f"{target_entity}.{target_field}")
        raise exc(message) if exc is not None else KeyError(message)

    def get(self, entity, pk_name, key, error=None):
        """One record by key, or `error` (default `KeyError`)."""
        try:
            return dict(self._space(entity)[key])
        except KeyError:
            message = f"{entity} with {pk_name}={key!r} not found"
            raise error(message) if error is not None else KeyError(message)

    def all(self, entity):
        """Every record of an entity, in insertion order."""
        return [dict(record) for record in self._space(entity).values()]

    def update(self, entity, pk_name, key, values, error=None):
        """Merge `values` into the record at `key`; unknown keys fail like `get`."""
        space = self._space(entity)
        if key not in space:
            message = f"{entity} with {pk_name}={key!r} not found"
            raise error(message) if error is not None else KeyError(message)
        merged = dict(space[key])
        for field_name, value in values.items():
            if value is not None:
                merged[field_name] = value
        space[key] = merged
        return dict(merged)

    def delete(self, entity, pk_name, key, error=None):
        """Remove the record at `key`; unknown keys fail like `get`."""
        space = self._space(entity)
        if key not in space:
            message = f"{entity} with {pk_name}={key!r} not found"
            raise error(message) if error is not None else KeyError(message)
        del space[key]

    def select(self, entity, criteria):
        """Records matching every `(field, operator, value)` criterion."""
        matches = []
        for record in self._space(entity).values():
            if all(_holds(record.get(field), operator, value)
                   for field, operator, value in criteria):
                matches.append(dict(record))
        return matches


def _holds(actual, operator, expected):
    if operator == "eq":
        return actual == expected
    if operator == "ge":
        return actual is not None and actual >= expected
    if operator == "le":
        return actual is not None and actual <= expected
    raise ValueError(f"unknown operator {operator!r}")

