def _qualify(pytype, entity_names):
    """Prefix bare entity references with `models.` so annotations resolve."""
    if not isinstance(pytype, str) or not entity_names:
        return pytype
    names = sorted({n for n in entity_names if isinstance(n, str)}, key=len, reverse=True)
    if not names:
        return pytype
    pattern = re.compile(r"(?<![\w.])(" + "|".join(re.escape(n) for n in names) + r")\b")
    return pattern.sub(r"models.\1", pytype)

def _option_dest(option):
    """The argparse dest for an option object (mirrors `_emit_options`)."""
    if not isinstance(option, dict):
        return None
    raw = (option.get("name") or option.get("short") or "").strip()
    if not raw.startswith("-"):
        raw = "--" + raw if raw else ""
    if not raw or raw.lstrip("-").lower() in ("help", "version"):
        return None
    return codegen.sanitize(raw.lstrip("-").replace("-", "_"), "opt")


def _bind_field(dests, field):
    """An option dest for an adapter field: exact match, else unique containment.

    CLI flags abbreviate (`--price` for `price_cents`, `--category` for
    `category_id`); containment in either direction resolves those, and an
    ambiguous or absent match is None — reported in the generation summary,
    enforced (for required fields) at runtime.
    """
    wanted = normalize(field or "")
    if not wanted:
        return None
    exact = [d for d in dests if normalize(d) == wanted]
    if len(exact) == 1:
        return exact[0]
    if exact:
        return None
    fuzzy = [d for d in dests
             if normalize(d) and (normalize(d) in wanted or wanted in normalize(d))]
    return fuzzy[0] if len(fuzzy) == 1 else None


def _action_argv(ctx, bindings):
    """`{action_name: {field_name: dest_or_None}}` over the bound leaves' flags."""
    leaves = {}
    for (command, sub), bound in bindings.items():
        if bound is None:
            continue
        options, _ = _leaf_options(ctx, command, sub)
        dests = [d for d in (_option_dest(o) for o in options) if d]
        leaves.setdefault(bound[0], []).append(dests)
    argv = {}
    for adapter in ctx["adapters"]:
        name = adapter.get("action_name")
        union = []
        for dests in leaves.get(name, []):
            union.extend(d for d in dests if d not in union)
        argv[name] = {}
        for field in adapter.get("input_fields") or []:
            if isinstance(field, dict) and field.get("field_name"):
                argv[name][field["field_name"]] = _bind_field(union, field["field_name"])
    return argv

