                normalize(p.get("name") or "")
                for p in candidate.get("params") or [] if isinstance(p, dict))
            if candidate_params != sorted(param_names):
                continue
            if normalize(_return_of(candidate, ctx["entity_names"])) != returns:
                continue
            return (cls, candidate)
    return None


