# --------------------------------------------------------------------------
# slotted patterns (human-answered slots -> mechanical bodies)
# --------------------------------------------------------------------------

# Required slots per pattern, from the kernel catalogues. COUNT needs no
# target (it counts rows); everything else does.
SLOT_REQUIREMENTS = {
    "AGGREGATE_BY_FK": ("fk_field", "target_field", "aggregate_func"),
    "AGGREGATE_BY_FK_AND_DATE": ("fk_field", "date_field", "target_field",
                                 "aggregate_func"),
    "THRESHOLD_SCAN": ("comparison_field", "operator", "threshold"),
}


def _slot_pattern(ctx, holder, method):
    """The slottable pattern id for a method, or None (with its slots)."""
    entry = _match_entry(ctx, holder, method.get("name"))
    if not isinstance(entry, dict):
        return None, {}
    kind, payload = tie_rules.effective_directive(entry)
    if kind != "pattern" or payload not in SLOT_PATTERNS:
        return None, {}
    record = ctx.get("slots", {}).get((holder, method.get("name")))
    if not isinstance(record, dict) or not isinstance(record.get("slots"), dict):
        return payload, {}
    return payload, record["slots"]


def _complete_slots(pattern, slots):
    """True when every required slot is answered (COUNT needs no target)."""
    required = SLOT_REQUIREMENTS.get(pattern, ())
    if pattern.startswith("AGGREGATE") and slots.get("aggregate_func") == "COUNT":
        required = tuple(slot for slot in required if slot != "target_field")
    return all(slots.get(slot) not in (None, "") for slot in required)


def _slot_fk_param(method, fk_field):
    """The parameter feeding the fk filter, or None when the method takes none."""
    if not fk_field:
        return None
    for param in method.get("params") or []:
        if isinstance(param, dict) and normalize(param.get("name") or "") == normalize(fk_field):
            return param.get("name")
    return None


def _slot_date_role(method):
    """`range`, `prefix:<param>` or None: how the signature carries dates."""
    names = [normalize(p.get("name") or "") for p in method.get("params") or []
             if isinstance(p, dict)]
    canon = [[c for c in codegen.canon_tokens(name)] for name in names]
    flat = [" ".join(tokens) for tokens in canon]
    has_start = any(tokens[:1] == ["start"] for tokens in canon)
    has_end = any(tokens[:1] == ["end"] for tokens in canon)
    if has_start and has_end:
        return "range"
    for name in names:
        if name in ("month", "year"):
            return f"prefix:{name}"
    _ = flat
    return None


def _repo_slot_body(ctx, entity, model_cls, field_names, method, pattern, slots):
    """An aggregate or threshold body from answered slots; None if unusable."""
    fname = method.get("name") if isinstance(method.get("name"), str) else "?"
    if pattern.startswith("AGGREGATE"):
        return _repo_aggregate_body(entity, model_cls, field_names, method,
                                    fname, slots)
    return _repo_threshold_body(entity, model_cls, field_names, method,
                                fname, slots)


def _repo_aggregate_body(entity, model_cls, field_names, method, fname, slots):
    """SUM/COUNT/AVG/MIN/MAX over records matching the fk and date slices."""
    func = slots.get("aggregate_func")
    target = slots.get("target_field")
    fk_param = _slot_fk_param(method, slots.get("fk_field"))
    date_role = _slot_date_role(method)
    date_field = slots.get("date_field")
    header = (f"{func}({target})" if func != "COUNT" else "COUNT") \
        + f" over {entity} matching " \
        + ", ".join(part for part in (
            f"{slots.get('fk_field')}={fk_param}" if fk_param else None,
            f"{date_field} in {date_role}" if date_role and date_field else None,
        ) if part) or "all records"
    lines = []
    if func == "COUNT":
        lines.append("count = 0")
    elif func == "AVG":
        lines += ["total = 0", "count = 0"]
    elif func in ("MIN", "MAX"):
        lines.append("best = None")
    else:
        lines.append("total = 0")
    lines.append(f"for record in self._store.select(self.ENTITY, []):")
    if fk_param:
        lines.append(f"    if {fk_param} is not None and "
                     f"record.get({slots['fk_field']!r}) != {fk_param}:")
        lines.append(f"        continue")
    if date_role == "range" and date_field:
        lines.append(f"    if start_date is not None and "
                     f"str(record.get({date_field!r}) or '') < str(start_date):")
        lines.append(f"        continue")
        lines.append(f"    if end_date is not None and "
                     f"str(record.get({date_field!r}) or '') > str(end_date):")
        lines.append(f"        continue")
    elif date_role and date_role.startswith("prefix:") and date_field:
        param = date_role.split(":", 1)[1]
        lines.append(f"    if {param} is not None and not "
                     f"str(record.get({date_field!r}) or '').startswith(str({param})):")
        lines.append(f"        continue")
    if func == "COUNT":
        lines.append("    count += 1")
    elif func == "AVG":
        lines.append(f"    total += record.get({target!r}) or 0")
        lines.append("    count += 1")
    elif func == "MIN":
        lines.append(f"    value = record.get({target!r})")
        lines.append("    best = value if best is None or (value is not None and value < best) else best")
    elif func == "MAX":
        lines.append(f"    value = record.get({target!r})")
        lines.append("    best = value if best is None or (value is not None and value > best) else best")
    else:
        lines.append(f"    total += record.get({target!r}) or 0")
    if func == "COUNT":
        lines.append("return count")
    elif func == "AVG":
        lines.append("return (total / count) if count else 0")
    elif func in ("MIN", "MAX"):
        lines.append("return best")
    else:
        lines.append("return total")
    lines[0:0] = [f'"""{header} [{func}]"""']
    return lines


def _repo_threshold_body(entity, model_cls, field_names, method, fname, slots):
    """Records whose field crosses the threshold: param, literal or today."""
    field = slots.get("comparison_field")
    operator = slots.get("operator")
    threshold = slots.get("threshold")
    ops = {"<": "<", "<=": "<=", ">": ">", ">=": ">=", "=": "=="}
    symbol = ops.get(operator, "<")
