    else:
        lines.append(f"bound = {threshold!r}")
    lines.append("out = []")
    lines.append(f"for record in self._store.select(self.ENTITY, []):")
    lines.append(f"    key = str(record.get({field!r}) or '')[:10]")
    lines.append(f"    if isinstance(bound, str):")
    lines.append(f"        hit = key {symbol} bound[:10]")
    lines.append(f"    else:")
    lines.append(f"        hit = record.get({field!r}) is not None and "
