    lines.append(f"    if hit:")
    lines.append(f"        record_out = record")
    if model_cls is None:
        lines.append(f"        out.append(dict(record_out))")
    else:
        lines.append(f"        out.append({model_cls}(**record_out))")
    lines.append("return out")
    lines[0:0] = [f'"""{entity} where {field} {operator} {threshold} [THRESHOLD_SCAN]"""']
    return lines

def _slot_date_role(method):
    """How the signature carries dates: `("range", start, end)`,
    `("prefix", param)` or None — param names verified, never assumed."""
    names = [p.get("name") for p in method.get("params") or []
