    pools = []
    for repo in ctx["repositories"]:
        names = {normalize(repo.get("interface_name") or ""),
                 normalize(repo.get("entity") or "")}
        if wanted in names:
            pools.append((repo.get("interface_name") or repo.get("entity"),
                          repo.get("methods") or []))
    for svc in ctx["services"]:
